// @ts-check

/**
 * Render a precomputed sweep. BUILD_PLANNER §7.3.
 *
 * The sweeps ship as data (`data/sweeps/*.json`, generated by `tools/sweep.mjs`) rather than
 * being re-run in the visitor's browser — decision 1. What matters here is that they do not
 * *look* like data: a swept figure and the live model above it go through the same
 * `paintCurves`, so they share axes, greyscale ramp, label spreading and log handling, and
 * read as two views of one thing rather than a chart and a screenshot.
 *
 * There is no `draw(world)` and no sampling. A sweep is finished; it just needs painting,
 * and repainting when the canvas resizes.
 */

import { paintCurves } from './curve.js';
import { drawAxes, fitCanvas, padded } from './axis.js';

/**
 * @typedef {object} SweepDoc
 * @property {string} id @property {string} title
 * @property {string|string[]} model @property {string} kind
 * @property {string} note @property {string} xLabel @property {string} [yLabel]
 * @property {number[]} xs
 * @property {{label: string, values: number[], dash?: boolean}[]} series
 * @property {{at: number, label: string}} [mark]
 * @property {'linear'|'log'} [yScale]
 * @property {number} points
 * @property {{x: number, y: number, stable?: boolean}[]} [scatter] set instead of `series`
 *   where the figure is a cloud rather than a curve — G1's tomahawk, where the same
 *   transport cost can have several equilibria and joining them would be a lie
 */

/**
 * @param {HTMLCanvasElement} canvas
 * @param {SweepDoc} sweep
 */
export function sweepView(canvas, sweep) {
  /** Last painted geometry, kept so a click can be mapped back to a swept value. */
  let painted = /** @type {ReturnType<typeof paintCurves>} */ (null);

  return {
    draw() {
      if (sweep.scatter) { paintScatter(canvas, sweep); painted = null; return; }
      painted = paintCurves(canvas, {
        xLabel: sweep.xLabel,
        yLabel: sweep.yLabel,
        curves: sweep.series.map((s) => ({ label: s.label, dash: s.dash })),
        xs: sweep.xs,
        ys: sweep.series.map((s) => s.values),
        yScale: sweep.yScale ?? 'linear',
        mark: sweep.mark,
      });
    },

    /**
     * The swept value under a click, or null if the click was outside the plot.
     *
     * This is what makes a sweep chart more than a picture: click the curve at ρ = 0.75 and
     * the live model above can be set there and run. Offered only where the model does not
     * drive that parameter itself — see `model.html`.
     *
     * @param {number} clientX @param {number} clientY
     */
    valueAt(clientX, clientY) {
      if (!painted) return null;
      const rect = canvas.getBoundingClientRect();
      const dpr = canvas.width / Math.max(rect.width, 1);
      const x = (clientX - rect.left) * dpr;
      const y = (clientY - rect.top) * dpr;
      const { box, xRange } = painted;
      if (x < box.left || x > box.right || y < box.top || y > box.bottom) return null;
      const t = (x - box.left) / (box.right - box.left);
      return xRange[0] + t * (xRange[1] - xRange[0]);
    },
  };
}

/**
 * A cloud of points rather than a curve.
 *
 * The tomahawk needs this and a line chart cannot carry it: at one transport cost there may
 * be one equilibrium or three, so there is no function to draw, and connecting the points in
 * x order would invent branches that do not exist. Stability is the second encoding — filled
 * black for stable, hollow grey for unstable — which is what turns a scatter into the figure
 * everyone recognises.
 *
 * @param {HTMLCanvasElement} canvas @param {SweepDoc} sweep
 */
function paintScatter(canvas, sweep) {
  const points = sweep.scatter ?? [];
  const { ctx, w, h, dpr } = fitCanvas(canvas);
  if (points.length === 0) return;

  const fontSize = Math.max(Math.round(h * 0.036), 9 * dpr);
  const box = { left: w * 0.12, right: w * 0.97, top: h * 0.07, bottom: h - fontSize * 3.4, dpr };
  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const xRange = padded(Math.min(...xs), Math.max(...xs), 0.02);
  const yRange = padded(Math.min(...ys, 0), Math.max(...ys, 1), 0.04);

  /** @param {number} v */
  const sx = (v) => box.left + ((v - xRange[0]) / (xRange[1] - xRange[0])) * (box.right - box.left);
  /** @param {number} v */
  const sy = (v) => box.bottom - ((v - yRange[0]) / (yRange[1] - yRange[0])) * (box.bottom - box.top);

  drawAxes(ctx, box, xRange, yRange, sx, sy, sweep.xLabel, sweep.yLabel);

  const r = Math.max(1.6 * dpr, 1.4);
  for (const p of points) {
    ctx.fillStyle = p.stable ? '#000' : 'rgba(0,0,0,0.32)';
    ctx.beginPath();
    ctx.arc(sx(p.x), sy(p.y), r, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.font = `${fontSize}px ui-monospace, Menlo, monospace`;
  ctx.textBaseline = 'top';
  ctx.textAlign = 'right';
  ctx.fillStyle = '#000';
  ctx.fillText('stable', box.right, box.top);
  ctx.fillStyle = 'rgba(0,0,0,0.45)';
  ctx.fillText('unstable', box.right, box.top + fontSize * 1.3);
  ctx.textAlign = 'left';
}

/**
 * Load the manifest and every sweep belonging to a model.
 *
 * Fails soft and says so: a missing `data/sweeps/` means the generator has not been run, and
 * that should leave the model page working with a quiet note rather than a broken section or
 * a console error nobody sees.
 *
 * @param {string} modelId
 * @returns {Promise<SweepDoc[]>}
 */
export async function sweepsFor(modelId) {
  /** @type {{id: string, model: string|string[]}[]} */
  let index;
  try {
    const response = await fetch('data/sweeps/index.json');
    if (!response.ok) return [];
    index = await response.json();
  } catch {
    return [];
  }

  const mine = index.filter((entry) => {
    const models = Array.isArray(entry.model) ? entry.model : [entry.model];
    return models.includes(modelId);
  });

  const loaded = await Promise.all(mine.map(async (entry) => {
    try {
      const response = await fetch(`data/sweeps/${entry.id}.json`);
      return response.ok ? /** @type {SweepDoc} */ (await response.json()) : null;
    } catch {
      return null;
    }
  }));
  return /** @type {SweepDoc[]} */ (loaded.filter(Boolean));
}
